import { dataset, dimension, divide, gte, measure, nullIfZero } from '@hypequery/datasets';

const DAY_GRAINS = ['day', 'week', 'month', 'quarter', 'year'] as const;

/** The raw fact table: a million rows, aggregated at query time. */
export const Events = dataset('events', {
  source: 'events',
  timeKey: 'occurred_at',
  dimensions: {
    eventId: dimension.number({ column: 'event_id' }),
    occurredAt: dimension.timestamp({ column: 'occurred_at' }),
    tenantId: dimension.number({ column: 'tenant_id' }),
    userId: dimension.number({ column: 'user_id' }),
    eventType: dimension.string({ column: 'event_type' }),
    statusCode: dimension.number({ column: 'status_code' }),
  },
  measures: {
    events: measure.count('eventId'),
    uniqueUsers: measure.countDistinct('userId'),
    errors: measure.count('statusCode', { filters: [gte('statusCode', 500)] }),
    errorRate: measure.derived({
      uses: { errors: 'errors', events: 'events' },
      formula: ({ errors, events }) => divide(errors, nullIfZero(events)),
    }),
  },
});

/**
 * Incremental rollup (sql/01-incremental.sql). Reads aggregate states, so
 * `measure.merge` applies `uniqExactMerge` and uniques stay exact at any grain.
 */
export const EventsDaily = dataset('eventsDaily', {
  source: 'events_daily',
  timeKey: 'day',
  timeGrains: [...DAY_GRAINS],
  dimensions: {
    day: dimension.timestamp(),
    tenantId: dimension.number({ column: 'tenant_id' }),
    eventType: dimension.string({ column: 'event_type' }),
  },
  measures: {
    events: measure.sum('events'),
    errors: measure.sum('errors'),
    uniqueUsers: measure.merge('uniqExact', 'users'),
    errorRate: measure.derived({
      uses: { errors: 'errors', events: 'events' },
      formula: ({ errors, events }) => divide(errors, nullIfZero(events)),
    }),
  },
});

/**
 * Refreshable rollup (sql/02-refreshable.sql). Final values per tenant-day,
 * including a JOIN to `tenants` and an exact p95, recomputed every hour.
 */
export const TenantDailySummary = dataset('tenantDailySummary', {
  source: 'tenant_daily_summary',
  timeKey: 'day',
  timeGrains: [...DAY_GRAINS],
  dimensions: {
    day: dimension.timestamp(),
    tenantId: dimension.number({ column: 'tenant_id' }),
    tenantName: dimension.string({ column: 'tenant_name' }),
    plan: dimension.string(),
  },
  measures: {
    events: measure.sum('events'),
    errors: measure.sum('errors'),
    worstP95LatencyMs: measure.max('p95_latency_ms', { label: 'Worst daily p95 latency (ms)' }),
    errorRate: measure.derived({
      uses: { errors: 'errors', events: 'events' },
      formula: ({ errors, events }) => divide(errors, nullIfZero(events)),
    }),
  },
});

'use client';

import { useState } from 'react';
import { BreakdownBars } from './breakdown-bars';
import { KpiTiles } from './kpi-tiles';
import { Timeseries } from './timeseries';
import {
  clearSelections,
  initialState,
  RANGE_PRESETS,
  rangeEndingAt,
  SEED_LAST_DAY,
  toDatasetFilters,
  toggleSelection,
  type CrossFilterState,
  type Dimension,
} from '@/lib/filters';

/**
 * The dashboard owns one piece of state: the date range plus the current
 * selections. Every panel derives its own dataset filters from it, so a click
 * in one panel re-queries all the others through the same `events` endpoint.
 */
export function Dashboard() {
  const [state, setState] = useState<CrossFilterState>(initialState);
  const select = (dimension: Dimension, value: string) =>
    setState((current) => toggleSelection(current, dimension, value));
  const activeDays = Math.round(
    (Date.parse(`${state.range.to}T00:00:00Z`) - Date.parse(`${state.range.from}T00:00:00Z`)) / 86_400_000,
  ) + 1;
  const selections = Object.entries(state.selections) as Array<[Dimension, string]>;

  return (
    <>
      <div className="toolbar" role="toolbar" aria-label="Filters">
        {RANGE_PRESETS.map((preset) => (
          <button
            key={preset.days}
            type="button"
            className="chip"
            aria-pressed={activeDays === preset.days}
            onClick={() => setState((current) => ({ ...current, range: rangeEndingAt(SEED_LAST_DAY, preset.days) }))}
          >
            Last {preset.label}
          </button>
        ))}
        <span className="spacer" />
        {selections.map(([dimension, value]) => (
          <button key={dimension} type="button" className="chip selection" onClick={() => select(dimension, value)}>
            {dimension}: {value} ×
          </button>
        ))}
        {selections.length > 0 && (
          <button type="button" className="chip" onClick={() => setState(clearSelections)}>
            Clear all
          </button>
        )}
      </div>

      <div className="grid">
        <KpiTiles filters={toDatasetFilters(state)} />
        <Timeseries filters={toDatasetFilters(state)} />
        <BreakdownBars
          title="Events by type"
          dimension="eventType"
          filters={toDatasetFilters(state, 'eventType')}
          selected={state.selections.eventType}
          onSelect={(value) => select('eventType', value)}
        />
        <BreakdownBars
          title="Events by device"
          dimension="device"
          filters={toDatasetFilters(state, 'device')}
          selected={state.selections.device}
          onSelect={(value) => select('device', value)}
        />
      </div>
    </>
  );
}
